from modele import chapitre,E,Q,tableau

chapitre(4,'racines','Carrés et racines carrées','1 · Nombres et calculs',
'Carrés parfaits · Racine carrée · Encadrement',
['Connaître les carrés des entiers de 0 à 12.','Comprendre la définition de la racine carrée d’un nombre positif.','Encadrer une racine carrée et passer d’une aire à une longueur.'],
['Multiplication, puissances et aire d’un carré.'],[
r'''\essSection{1}{Du carré à sa racine}
\begin{definition}Le carré d’un nombre $a$ est $a^2=a\times a$ ; il est toujours positif ou nul. On admet que, pour tout nombre $b$ positif, il existe un unique nombre positif dont le carré vaut $b$ : c’est la racine carrée de $b$, notée $\sqrt b$. Ainsi $\sqrt{49}=7$ car $7^2=49$, et $\sqrt0=0$.\end{definition}
\begin{center}\begin{tabular}{c|rrrrrr}\toprule
$n$ & 1 & 2 & 3 & 4 & 5 & 6\\\midrule
$n^2$ & 1 & 4 & 9 & 16 & 25 & 36\\\midrule
$n$ & 7 & 8 & 9 & 10 & 11 & 12\\\midrule
$n^2$ & 49 & 64 & 81 & 100 & 121 & 144\\\bottomrule
\end{tabular}\end{center}
\begin{exemple}L’aire d’un carré est 81 cm$^2$. On cherche le nombre positif qui, multiplié par lui-même, donne 81 : $9\times9=81$, donc le côté mesure $\sqrt{81}=9$ cm. Un carré d’aire 30 cm$^2$ a un côté de $\sqrt{30}$ cm.\end{exemple}
\begin{attention}$\sqrt{25}=5$ seulement. Les deux nombres 5 et $-5$ ont pour carré 25, mais le symbole racine carrée désigne le nombre positif. Aucun nombre n’a pour carré $-9$ : $\sqrt{-9}$ n’existe pas.\end{attention}''',
r'''\essSection{2}{Encadrer et approcher}
\begin{savoirfaire}[Utiliser les carrés connus]Comme $25<30<36$, on sait que $5<\sqrt{30}<6$ : $\sqrt{30}$ est encadré par deux entiers consécutifs. Pour affiner, comparer des carrés décimaux : $5{,}4^2=29{,}16$ et $5{,}5^2=30{,}25$, donc $5{,}4<\sqrt{30}<5{,}5$.\end{savoirfaire}
\begin{exemple}La calculatrice donne $\sqrt{30}\approx5{,}477225\ldots$ Au centième, on écrit $\sqrt{30}\approx5{,}48$. Le signe « $=$ » reste réservé à l’égalité exacte. Le périmètre exact du carré d’aire 30 cm$^2$ est $4\sqrt{30}$ cm, environ 21,91 cm.\end{exemple}
\begin{savoirfaire}[Relier aire et longueur]Calculer d’abord l’aire cherchée si nécessaire, puis prendre sa racine carrée. Garder la valeur exacte dans les calculs intermédiaires et n’arrondir que le résultat final.\end{savoirfaire}
\begin{attention}Une racine ne se répartit pas sur une somme : $\sqrt{9+16}=5$, alors que $\sqrt9+\sqrt{16}=7$. Les transformations d’écritures avec des racines ne sont pas un objectif de Quatrième.\end{attention}
\begin{exemple}[Repère historique]La diagonale d’un carré de côté 1 mesure $\sqrt2$, car le carré construit sur elle a pour aire 2. Les mathématiciens grecs ont découvert que ce nombre ne s’écrit pas comme un quotient d’entiers. Le défi D04 montre déjà qu’il n’est pas décimal.\end{exemple}'''],[
E('Les carrés connus',r"Calculer $7^2$, $11^2$ et $12^2$.",r"$7\times7=\res{49}$, $11\times11=\res{121}$ et $12\times12=\res{144}$. Ces carrés sont des repères à mémoriser pour encadrer ensuite des racines.","Relier chaque carré à un produit.","assert (7**2,11**2,12**2)==(49,121,144)"),
E('Lire trois racines',r"Donner $\sqrt{64}$, $\sqrt{100}$ et $\sqrt{0}$.",r"$8^2=64$, $10^2=100$ et $0^2=0$. Les racines demandées sont donc $\res8$, $\res{10}$ et $\res0$, toutes positives ou nulles.","Chercher le nombre positif dont le carré convient.","assert sqrt(64)==8 and sqrt(100)==10 and sqrt(0)==0"),
E('Un signe à expliquer',r"Pourquoi $\sqrt{81}$ ne vaut-il pas $-9$ ?",r"Même si $(-9)^2=81$, une racine carrée est par définition positive ou nulle. On écrit donc $\res{\sqrt{81}=9}$.","Utiliser la définition et non seulement le carré.","assert (-9)**2==81 and sqrt(81)==9"),
E('Encadrer entre deux entiers',r"Encadrer $\sqrt{53}$ entre deux entiers consécutifs.",r"$7^2=49<53<64=8^2$, donc $\res{7<\sqrt{53}<8}$. Aucun calcul approché n’est nécessaire.","Placer le nombre entre deux carrés parfaits.","assert 7<sqrt(53)<8"),
E('De l’aire au côté',r"Un carré a une aire de $121\ \mathrm{cm}^2$. Quelle est la longueur de son côté ?",r"Si le côté est $c$, son aire vaut $c^2$. La longueur cherchée est donc $\sqrt{121}=\res{11\ \mathrm{cm}}$. L’unité passe de cm$^2$ à cm.","Inverser le calcul de l’aire du carré.","assert sqrt(121)==11",figure='carre-121'),
E('Une valeur approchée',r"Donner une valeur approchée de $\sqrt{19}$ au centième et un encadrement par deux dixièmes consécutifs.",r"La calculatrice donne $4{,}358898\ldots$, donc $\sqrt{19}\approx\res{4{,}36}$. De plus $4{,}3^2=18{,}49<19<19{,}36=4{,}4^2$, d’où $\res{4{,}3<\sqrt{19}<4{,}4}$.","Vérifier l’arrondi avec un encadrement.","assert Rational('4.3')<sqrt(19)<Rational('4.4') and round(float(sqrt(19)),2)==4.36"),
E('Périmètre exact',r"Un carré a une aire de $18\ \mathrm{m}^2$. Donner son périmètre exact, puis arrondi au centième de mètre.",r"Le côté vaut $\sqrt{18}$ m, donc le périmètre exact est $\res{4\sqrt{18}\ \mathrm m}$. On calcule ensuite $4\sqrt{18}\approx\res{16{,}97\ \mathrm m}$. Arrondir le côté avant de le multiplier ferait perdre de la précision.","Arrondir seulement le résultat final.","assert round(float(4*sqrt(18)),2)==16.97",figure='carre-18'),
E('Deux aires',r"Comparer les côtés de deux carrés d’aires 42 et 45 cm$^2$, puis encadrer leur différence entre 0 et 1 cm.",r"$42<45$, donc $\sqrt{42}<\sqrt{45}$. Les deux côtés sont entre 6 et 7 cm car $36<42<45<49$. Leur différence est ainsi strictement comprise entre $\res0$ et $\res1$ cm.","Comparer les carrés puis leurs racines positives.","assert 0<sqrt(45)-sqrt(42)<1"),
E('Détecter une fausse règle',r"Camille propose $\sqrt{36+64}=\sqrt{36}+\sqrt{64}$. Calculer les deux membres et conclure.",r"Le membre de gauche vaut $\sqrt{100}=\res{10}$. Celui de droite vaut $6+8=\res{14}$. L’égalité est fausse : on ne peut pas répartir la racine sur une somme. Un seul contre-exemple suffit.","Calculer chaque membre indépendamment.","assert sqrt(36+64)==10 and sqrt(36)+sqrt(64)==14"),
E('Arrondi ou troncature',r"Un élève écrit $\sqrt{50}=7{,}07$. Corriger l’écriture et expliquer si 7,07 est un arrondi au centième.",r"$7{,}07^2=49{,}9849$, différent de 50 : le signe d’égalité est faux. $\sqrt{50}=7{,}071067\ldots$, donc $\res{\sqrt{50}\approx7{,}07}$ est bien l’arrondi au centième ; ici la troncature donne la même valeur.","Distinguer égalité exacte et approximation.","assert Rational('7.07')**2!=50 and round(float(sqrt(50)),2)==7.07"),
E('Un jardin carré',r"Un jardin carré de 72 m$^2$ est entouré d’une clôture sauf sur une ouverture de 2 m. Quelle longueur de clôture prévoir, au dixième de mètre ?",r"Le côté vaut $\sqrt{72}$ m. La longueur à clôturer est donc $4\sqrt{72}-2\approx\res{31{,}9\ \mathrm m}$. On soustrait l’ouverture une seule fois au périmètre.","Calculer le périmètre avant de retirer l’ouverture.","assert round(float(4*sqrt(72)-2),1)==31.9",figure='jardin-72'),
E('Passer par une conversion',r"Un carré a une aire de $6\,400\ \mathrm{cm}^2$. Donner son côté en centimètres, puis en mètres.",r"$\sqrt{6\,400}=\res{80}$ cm, soit $\res{0{,}8}$ m. On peut contrôler : $0{,}8^2=0{,}64$ m$^2$, ce qui correspond à 6 400 cm$^2$. Une conversion d’aire ne se fait pas avec le même facteur qu’une longueur.","Extraire une longueur puis convertir son unité.","assert sqrt(6400)==80 and Rational(80,100)==Rational('.8')"),
E('Une aire multipliée',r"Un carré de côté 3 cm est remplacé par un carré d’aire cinq fois plus grande. Donner le nouveau côté exact et approché au millimètre.",r"L’aire initiale vaut 9 cm$^2$, la nouvelle 45 cm$^2$. Le côté vaut $\res{\sqrt{45}\ \mathrm{cm}}$, soit environ $\res{6{,}7\ \mathrm{cm}}$ au millimètre. Multiplier l’aire par 5 ne multiplie pas le côté par 5.","Revenir à l’aire avant de prendre la racine.","assert round(float(sqrt(45)),1)==6.7 and sqrt(45)**2==5*3**2",figure='carre-45'),
E('Un encadrement précis',r"Sans touche racine, encadrer $\sqrt{10}$ entre deux centièmes consécutifs en testant 3,16 et 3,17.",r"$3{,}16^2=9{,}9856$ et $3{,}17^2=10{,}0489$. Le nombre 10 est entre ces deux carrés, donc $\res{3{,}16<\sqrt{10}<3{,}17}$. Cet encadrement ne suffit pas seul à choisir l’arrondi au centième : il faudrait situer la racine par rapport à 3,165.","Ne pas confondre encadrement et arrondi.","assert Rational('3.16')**2<10<Rational('3.17')**2"),
E('Une plaque dans une boîte',r"Une plaque carrée de 50 cm$^2$ doit entrer dans une boîte dont le fond intérieur est un carré de côté 7 cm, les côtés restant parallèles. Est-ce possible ? Quelle aire maximale conviendrait ?",r"Le côté de la plaque vaut $\sqrt{50}$ cm. Comme $7^2=49<50$, il dépasse 7 cm : la plaque ne rentre pas dans cette position. L’aire maximale d’une plaque carrée de côté 7 cm est $\res{49\ \mathrm{cm}^2}$. Une approximation grossière à 7 aurait masqué le dépassement.","Comparer des carrés pour une décision exacte.","assert sqrt(50)>7 and 7**2==49",figure='plaque-50')
],reperes=['Carrés parfaits de 0 à 144','Définition de la racine carrée','Encadrements et valeurs approchées','Aires et longueurs exactes'],deco='calcul')

chapitre(5,'litteral','Expressions, distributivité et preuves','2 · Algèbre et modèles',
'Formules · Développer · Factoriser · Démontrer',
['Produire une formule et lire la structure d’une expression.','Développer et factoriser par distributivité simple.','Utiliser le calcul littéral pour démontrer une propriété générale.'],
['Produits de relatifs et priorités opératoires.'],[
r'''\essSection{1}{Une lettre pour plusieurs valeurs}
\begin{definition}Une expression littérale contient des lettres qui représentent des nombres. $3x$ signifie $3\times x$, et $x^2$ signifie $x\times x$. Calculer la valeur d’une expression consiste à remplacer chaque lettre par la valeur donnée, en conservant des parenthèses autour d’un nombre négatif.\end{definition}
\begin{exemple}Pour $x=-2$, $3x^2-5x=3\times(-2)^2-5\times(-2)=12+10=22$. $3x+4$ est une somme ; $3(x+4)$ est un produit. L’opération effectuée en dernier détermine la structure.\end{exemple}
\begin{propriete}Réduire consiste à regrouper les termes de même nature : $5x+2x-3=7x-3$, $x\times x=x^2$ et $3x\times2x=6x^2$. En revanche, $x$ et $x^2$ ne sont pas des termes de même nature : $x+x^2$ ne se réduit pas.\end{propriete}
\begin{definition}[Écrire un nombre quelconque]Pour tout entier $n$, $2n$ est un nombre pair et $2n+1$ un nombre impair ; $n$ et $n+1$ sont deux entiers consécutifs. Une formule produite doit être testée sur un exemple pour contrôler sa vraisemblance.\end{definition}
\begin{attention}Tester une égalité pour quelques nombres peut trouver une erreur, mais ne prouve pas qu’elle est vraie pour toutes les valeurs. Pour une preuve générale, on transforme les expressions avec des propriétés vraies pour tous les nombres.\end{attention}''',
r'''\essSection{2}{La distributivité dans les deux sens}
\begin{propriete}Pour tous nombres $k$, $a$, $b$ : $k(a+b)=ka+kb$ et $k(a-b)=ka-kb$, ainsi que $(a+b)k=ak+bk$. Passer du produit à la somme s’appelle développer. Passer de la somme au produit s’appelle factoriser ; on repère alors un facteur commun.\end{propriete}
\begin{exemple}$-3(2x-5)=-6x+15$. Le facteur $-1$ explique l’opposé d’une expression : $-(4x-2)=-1\times(4x-2)=-4x+2$. Dans l’autre sens, $12x^2+8x=4x(3x+2)$ et $x^2-x=x(x-1)$.\end{exemple}
@FIG:cours-distributivite@
\begin{savoirfaire}[Démontrer avec une lettre]Choisir une lettre pour le nombre de départ. Écrire l’expression de chaque programme, puis développer et réduire. Obtenir la même expression prouve qu’ils donnent le même résultat pour tout nombre de départ.\end{savoirfaire}
\begin{attention}On simplifie des facteurs d’un produit, pas des termes séparés par une addition. Les produits de deux parenthèses et les identités remarquables seront étudiés en Troisième.\end{attention}'''],[
E('Lire la structure',r"Dire si $5x+15$, $5(x+3)$ et $x(2x-1)$ sont des sommes ou des produits.",r"$5x+15$ est une $\res{\text{somme}}$ de deux termes. $5(x+3)$ et $x(2x-1)$ sont des $\res{\text{produits}}$ : leur dernière opération est une multiplication. Les parenthèses contiennent elles-mêmes une somme ou une différence.","Repérer l’opération extérieure.","assert expand(5*(x+3))==5*x+15 and degree(x*(2*x-1),x)==2"),
E('Substituer un négatif',r"Calculer $A=4x-7$ pour $x=-3$.",r"On remplace $x$ par $-3$ : $A=4\times(-3)-7=-12-7=\res{-19}$. Les parenthèses montrent le nombre remplacé.","Remplacer chaque lettre avant de calculer.","assert (4*x-7).subs(x,-3)==-19"),
E('Réduire',r"Réduire $8x-3+2x+7$, puis $3x\times2x+x^2$.",r"Les termes en $x$ donnent $8x+2x=10x$ et les constantes $-3+7=4$ : $\res{10x+4}$. Ensuite $3x\times2x=6x^2$, donc $6x^2+x^2=\res{7x^2}$.","Regrouper les termes de même nature.","assert expand(8*x-3+2*x+7)==10*x+4 and expand(3*x*2*x+x**2)==7*x**2"),
E('Supprimer des parenthèses',r"Écrire sans parenthèses puis réduire : $-(5-4x)$ et $2x-(3x-1)$.",r"Prendre l’opposé change le signe de chaque terme : $-(5-4x)=\res{-5+4x}$. De même $2x-(3x-1)=2x-3x+1=\res{-x+1}$.","Multiplier chaque terme par $-1$.","assert expand(-(5-4*x))==4*x-5 and expand(2*x-(3*x-1))==1-x"),
E('Factoriser',r"Factoriser $18x+30$ avec le plus grand facteur entier commun.",r"Le facteur commun est 6 : $18x+30=6\times3x+6\times5=\res{6(3x+5)}$. Redévelopper permet de vérifier.","Chercher le facteur commun aux deux termes.","assert gcd(18,30)==6 and expand(6*(3*x+5))==18*x+30"),
E('Distribuer un signe négatif',r"Développer et réduire $-2(5x-4)+3x$.",r"$-2(5x-4)=-10x+8$, puis $-10x+8+3x=\res{-7x+8}$. Le terme $+8$ vient de $(-2)\times(-4)$.","Contrôler le signe de chaque produit.","assert expand(-2*(5*x-4)+3*x)==-7*x+8"),
E('Un facteur littéral',r"Développer et réduire $3x(2x+5)-4x$.",r"$3x\times2x=6x^2$ et $3x\times5=15x$. On obtient $6x^2+15x-4x=\res{6x^2+11x}$. Les termes en $x^2$ et en $x$ restent séparés.","Utiliser $x\times x=x^2$.","assert expand(3*x*(2*x+5)-4*x)==6*x**2+11*x"),
E('Factoriser avec une lettre',r"Factoriser $15x^2-10x$.",r"Chaque terme contient $5x$ : $15x^2=5x\times3x$ et $-10x=5x\times(-2)$. Donc $\res{5x(3x-2)}$.","Mettre en évidence le facteur numérique et littéral.","assert expand(5*x*(3*x-2))==15*x**2-10*x"),
E('Équivalence de programmes',r"Programme A : ajouter 4 à un nombre, puis multiplier par 3. Programme B : tripler le nombre, puis ajouter 12. Sont-ils équivalents ?",r"Pour un nombre $x$, A donne $3(x+4)=3x+12$ et B donne $3x+12$. Les deux expressions sont identiques pour tout $x$ : les programmes sont $\res{\text{équivalents}}$.","Traduire les deux programmes avec la même lettre.","assert expand(3*(x+4))==3*x+12"),
E('Réparer une réduction',r"Un élève écrit $4x+3x^2=7x^3$. Expliquer son erreur et donner la valeur de l’expression pour $x=2$.",r"On ne regroupe pas des termes de natures différentes. La somme reste $4x+3x^2$. Pour $x=2$, elle vaut $8+12=\res{20}$, tandis que $7x^3$ vaudrait 56 : ce contre-exemple réfute l’égalité.","Vérifier les termes avant de les regrouper.","assert (4*x+3*x**2).subs(x,2)==20 and (7*x**3).subs(x,2)==56"),
E('Une aire composée',r"Un rectangle a pour hauteur 4 cm et pour largeur $x+3$ cm, avec $x>0$. Exprimer son aire de deux façons.",r"Par la formule du rectangle, $A=4(x+3)$. En partageant la largeur en $x$ et 3, on obtient deux aires $4x$ et 12. Ainsi $\res{A=4x+12\ \mathrm{cm}^2}$. Cette décomposition illustre la distributivité.","Additionner les aires des deux rectangles.","assert expand(4*(x+3))==4*x+12",figure='aire-distrib'),
E('Un périmètre variable',r"Un rectangle mesure $2x+1$ cm sur $x+3$ cm, avec $x>0$. Exprimer puis réduire son périmètre. Le calculer pour $x=4$.",r"$P=2(2x+1)+2(x+3)=4x+2+2x+6=\res{6x+8}$ cm. Pour $x=4$, $P=24+8=\res{32}$ cm. Les côtés valent alors 9 et 7 cm, d’où $2(9+7)=32$ : la formule est vraisemblable.","Compter deux fois chaque dimension.","assert expand(2*(2*x+1)+2*(x+3))==6*x+8 and (6*x+8).subs(x,4)==32",figure='rectangle-litteral'),
E('Un calcul mental justifié',r"Calculer $39\times27+61\times27$ sans poser deux multiplications. Expliquer la propriété utilisée.",r"Le facteur commun est 27 : $39\times27+61\times27=(39+61)\times27=100\times27=\res{2\,700}$. On a utilisé la distributivité dans le sens de la factorisation.","Repérer un facteur commun avant de calculer.","assert 39*27+61*27==2700"),
E('Trois entiers consécutifs',r"Montrer que la somme de trois entiers consécutifs est toujours un multiple de 3. Que vaut-elle quand le premier entier est 41 ?",r"On appelle $n$ le premier entier ; les suivants sont $n+1$ et $n+2$. Leur somme est $n+(n+1)+(n+2)=3n+3=\res{3(n+1)}$ : c’est un multiple de 3 pour tout entier $n$. Pour $n=41$, elle vaut $3\times42=\res{126}$. Un seul exemple n’aurait pas suffi à le démontrer.","Représenter les trois entiers avec une seule lettre.","assert expand(n+(n+1)+(n+2))==3*n+3 and 41+42+43==126"),
E('Une différence constante',r"Programme A : multiplier le nombre de départ par 5 puis retirer 7. Programme B : retirer 2 au nombre, multiplier par 5 puis ajouter 6. Montrer que l’écart A moins B est constant.",r"A donne $5x-7$. B donne $5(x-2)+6=5x-4$. Leur différence est $(5x-7)-(5x-4)=\res{-3}$. A donne donc toujours 3 de moins que B, quel que soit $x$. La lettre disparaît dans la différence.","Soustraire des expressions entre parenthèses.","assert expand((5*x-7)-(5*(x-2)+6))==-3")
],reperes=['Structure, substitution et réduction','Développer par distributivité simple','Factoriser avec un facteur commun','Formules, programmes et preuves'],deco='calcul')

chapitre(6,'equations','Équations du premier degré','2 · Algèbre et modèles',
'Inconnue · Égalités équivalentes · Mise en équation · Vérification',
['Tester si un nombre est solution d’une équation.','Résoudre une équation du premier degré.','Mettre un problème en équation, résoudre et interpréter.'],
['Calcul littéral et nombres relatifs.'],[
r'''\essSection{1}{Conserver l’égalité}
\begin{definition}Une équation est une égalité contenant une inconnue. Une solution est une valeur qui rend cette égalité vraie. Résoudre une équation consiste à trouver toutes ses solutions.\end{definition}
\begin{propriete}Ajouter ou soustraire un même nombre aux deux membres conserve les solutions. Multiplier ou diviser les deux membres par un même nombre non nul conserve aussi les solutions. Ces transformations permettent d’isoler l’inconnue.\end{propriete}
\begin{exemple}$3x+5=17$. On soustrait 5 aux deux membres : $3x=12$. On divise par 3 : $x=4$. Contrôle : $3\times4+5=17$. La solution est bien 4.\end{exemple}
@FIG:cours-equilibre@
\begin{attention}« Passer de l’autre côté » doit correspondre à une opération faite aux deux membres. On ne change pas arbitrairement un signe ou une multiplication en addition.\end{attention}''',
r'''\essSection{2}{Du problème à la réponse}
\begin{savoirfaire}[Une méthode en quatre temps]1. Choisir l’inconnue et son unité. 2. Traduire la relation par une équation. 3. Résoudre en écrivant des égalités équivalentes. 4. Contrôler dans le contexte et formuler une phrase de réponse.\end{savoirfaire}
\begin{exemple}$5x-4=2x+8$ donne $3x-4=8$, puis $3x=12$ et $x=4$. Pour $2(x+3)=x+11$, développer donne $2x+6=x+11$, donc $x=5$.\end{exemple}
\begin{savoirfaire}[Plusieurs termes]Développer les parenthèses, réduire chaque membre, réunir les termes en $x$ d’un côté et les constantes de l’autre. Un tableur ou un algorithme permet de tester de nombreuses valeurs pour conjecturer une solution, exacte ou approchée ; le calcul la confirme ensuite.\end{savoirfaire}
\begin{attention}Une solution calculée doit respecter le problème : longueur positive, effectif entier, temps possible. Une égalité finale impossible comme $0=3$ signifie qu’il n’y a pas de solution ; une égalité toujours vraie comme $0=0$ signifie que tous les nombres conviennent.\end{attention}'''],[
E('Tester une valeur',r"Le nombre 4 est-il solution de $3x-2=10$ ? Le nombre 5 l’est-il ?",r"Pour 4, $3\times4-2=10$ : $\res4$ est solution. Pour 5, $3\times5-2=13\ne10$ : 5 n’est pas solution. Tester consiste à calculer les deux membres.","Substituer sans transformer l’équation.","assert (3*x-2).subs(x,4)==10 and (3*x-2).subs(x,5)!=10"),
E('Une addition',r"Résoudre $x+8=-3$.",r"On soustrait 8 aux deux membres : $x=-3-8=\res{-11}$. Vérification : $-11+8=-3$.","Effectuer la même soustraction dans les deux membres.","assert solve(x+8+3,x)==[-11]"),
E('Un coefficient négatif',r"Résoudre $-4x=18$.",r"On divise par $-4$, nombre non nul : $x=\frac{18}{-4}=\res{-\frac92}$, soit $-4{,}5$. Le produit $(-4)\times(-4{,}5)=18$ confirme.","Diviser les deux membres par le coefficient de l’inconnue.","assert solve(-4*x-18,x)==[Rational(-9,2)]"),
E('Deux étapes',r"Résoudre $5x-7=23$.",r"On ajoute 7 : $5x=30$. On divise par 5 : $\res{x=6}$. Contrôle : $5\times6-7=23$.","Enlever la constante avant le coefficient.","assert solve(5*x-7-23,x)==[6]"),
E('Traduire une phrase',r"Le triple d’un nombre augmenté de 4 vaut 25. Écrire l’équation puis trouver le nombre.",r"Si le nombre est $x$, la phrase donne $3x+4=25$. Donc $3x=21$ puis $\res{x=7}$. Contrôle : $3\times7+4=25$.","Distinguer le triple du nombre et l’ajout final.","assert solve(3*x+4-25,x)==[7]"),
E('L’inconnue des deux côtés',r"Résoudre $7x-5=3x+11$.",r"On soustrait $3x$ : $4x-5=11$. On ajoute 5 : $4x=16$, puis $\res{x=4}$. Les deux membres valent 23 pour $x=4$.","Réunir les termes en $x$ dans un membre.","assert solve(7*x-5-(3*x+11),x)==[4]"),
E('Avec une parenthèse',r"Résoudre $3(x-2)=x+8$.",r"On développe : $3x-6=x+8$. On soustrait $x$ et on ajoute 6 : $2x=14$, donc $\res{x=7}$. Contrôle : $3(7-2)=15=7+8$.","Développer avant de regrouper.","assert solve(3*(x-2)-(x+8),x)==[7]"),
E('Avec des fractions',r"Résoudre $\frac{x}{3}+\frac12=\frac52$.",r"On soustrait $\frac12$ : $\frac x3=\frac42=2$. On multiplie par 3 : $\res{x=6}$. Contrôle : $\frac63+\frac12=\frac52$.","Simplifier les constantes avant de multiplier.","assert solve(x/3+Rational(1,2)-Rational(5,2),x)==[6]"),
E('Corriger une méthode',r"Un élève résout $2x+6=14$ en écrivant $x+6=7$, puis $x=1$. Corriger.",r"En divisant par 2, il faut diviser tout le membre : $x+3=7$, donc $\res{x=4}$. On peut aussi soustraire 6 d’abord : $2x=8$. Le contrôle donne $2\times4+6=14$.","Appliquer une opération au membre entier.","assert solve(2*x+6-14,x)==[4]"),
E('Conjecturer avec un tableur',r"Dans un tableur, la colonne A contient les nombres 0 à 6, la colonne B la formule \texttt{=5*A2-7} et la colonne C la formule \texttt{=2*A2+5}, recopiées vers le bas. Pour quelle valeur les colonnes B et C sont-elles égales ? Confirmer par le calcul.",r"La ligne $x=4$ affiche 13 dans les deux colonnes : on conjecture la solution 4. L’équation $5x-7=2x+5$ donne $3x=12$, donc $\res{x=4}$ ; la conjecture est prouvée. Le tableau seul ne montrait pas qu’il n’existe pas d’autre solution entre les valeurs testées.","Lire le tableau, puis résoudre l’équation.","assert [5*a-7 for a in range(7)][4]==[2*a+5 for a in range(7)][4]==13 and solve(5*x-7-(2*x+5),x)==[4]",figure='tableur-equation'),
E('Un rectangle',r"Un rectangle a une largeur $x$ cm et une longueur $x+5$ cm. Son périmètre est 38 cm. Trouver ses dimensions.",r"$2x+2(x+5)=38$, soit $4x+10=38$. Donc $4x=28$ et $\res{x=7}$. La largeur est 7 cm et la longueur $\res{12}$ cm. Contrôle : $2(7+12)=38$ cm, avec deux dimensions positives.","Traduire le périmètre avec la même inconnue.","assert solve(2*x+2*(x+5)-38,x)==[7]",figure='eq-rectangle'),
E('Deux tarifs',r"Le tarif A coûte 12 euros puis 3 euros par entrée. Le tarif B coûte 5 euros par entrée. Pour combien d’entrées les dépenses sont-elles égales ?",r"Pour $x$ entrées : $12+3x=5x$. Donc $12=2x$, soit $\res{x=6}$. Les deux dépenses valent alors $\res{30}$ euros. Le nombre d’entrées obtenu est bien entier et positif.","Égaler les deux expressions de coût.","assert solve(12+3*x-5*x,x)==[6] and 12+3*6==5*6==30"),
E('Des entiers consécutifs',r"La somme de trois entiers consécutifs vaut 81. Les trouver.",r"On note $n$ le premier ; les deux suivants sont $n+1$ et $n+2$. $3n+3=81$ donne $3n=78$ puis $n=26$. Les nombres sont $\res{26,\ 27,\ 28}$ et leur somme est bien 81.","Exprimer tous les nombres avec une inconnue.","assert solve(x+(x+1)+(x+2)-81,x)==[26]"),
E('Un âge futur',r"Maya a 12 ans et son père 40 ans. Dans combien d’années l’âge du père sera-t-il le double de celui de Maya ?",r"Dans $x$ années, les âges seront $12+x$ et $40+x$. On écrit $40+x=2(12+x)$. Donc $40+x=24+2x$ et $\res{x=16}$. Les âges seront 28 et 56 ans : le second est bien le double du premier.","Faire augmenter les deux âges du même nombre d’années.","assert solve(40+x-2*(12+x),x)==[16]"),
E('Une longueur admissible',r"Un triangle équilatéral de côté $x+2$ cm et un carré de côté $x$ cm ont le même périmètre. Trouver $x$, puis vérifier que les figures existent.",r"$3(x+2)=4x$ donne $3x+6=4x$, donc $\res{x=6}$. Le carré a pour côté 6 cm et le triangle 8 cm : les deux longueurs sont positives. Les périmètres valent chacun $\res{24}$ cm.","Résoudre puis contrôler les contraintes de longueur.","assert solve(3*(x+2)-4*x,x)==[6] and 3*8==4*6==24",figure='eq-deux-figures')
],reperes=['Inconnue et test d’une solution','Équations du premier degré','Mise en équation et vérification','Tableur, conjecture et interprétation'],deco='calcul')
